/// even though the analogous `generated`/`derived` grant was already refused. Checking each control's exemption
/// separately here, by hand, is the same enumeration pattern one level up — so this compares through the single
/// authoritative table instead ([`crate::paths::confers_any_exemption`]): a candidate that would confer ANY
/// exemption the kernel's overlapped rule did not already confer is refused, independently of every field below,
/// because an observed-or-included path becoming exempt from ANY governed control is a widening that
/// dimension-by-dimension comparison cannot see on its own (P2-AR-0075's own witness: `{pattern: "product/*.yaml",
/// class: derived}`, equal-or-stricter on every field this function already checked, still turned a refused
/// `MUTATION_SCOPE_VIOLATION` into an accepted close; AR77-F3's witness, the same shape with `class: evidence`,
/// turned a refused `EXPERIMENT_OUTPUT_IN_PRODUCTION` into an accepted one). A candidate that confers no exemption
/// at all — including one that merely carries a different, non-exempting label such as `authoritative` — is
/// untouched by this: the check below has nothing to say about a rule that was never eligible to widen anything
/// this table knows about. A class newly added to [`crate::paths::CLASS_EXEMPTIONS`] for a future control is
/// protected here automatically, with no change to this function.
pub(crate) fn overlap_is_no_less_restrictive(kernel: &Value, new: &Value) -> std::result::Result<(), String> {
    let k = rule_effective_attrs(kernel);
    let n = rule_effective_attrs(new);
    let (kc, nc) = (k.class(), n.class());
    let newly_conferred: Vec<crate::paths::Exemption> = crate::paths::class_exemptions(&nc)
        .iter()
        .filter(|e| !crate::paths::class_confers(&kc, **e))
        .copied()
        .collect();
    if !newly_conferred.is_empty() {
        return Err(format!(
            "class would be '{nc}' instead of '{kc}', which confers {} the kernel's overlapped classification does \
             not -- a path becoming exempt from a governed control it was not exempt from before is a widening \
             even when every other compared dimension looks equal or stricter (AR75-F2, AR77-F3, OD-P2-07)",
            describe_exemptions(&newly_conferred)
        ));
    }
    // AR73-F3 fallout, discovered by the one genuine full suite run: once `glob_segments` correctly models
    // `glob_match`'s implicit `**/<pattern>` rule, a single-segment `class: secret` declaration (adoption A2's
    // own generator, `adopt.rs` line ~1520, uses the discovered file's path VERBATIM as the pattern -- a
    // root-level `.env` file becomes exactly the pattern `.env`) now correctly overlaps many more kernel
    // directories than before, including highly restrictive ones (`governance/kernel/**`). Such a rule
    // legitimately leaves `mutation` unset, defaulting through `class_defaults` to "allowed" -- the SAME
    // convention the kernel's OWN secret rules use (AR73-F3's own finding: "the kernel's own `**/.env*` rule
    // does not set mutation either ... the floor for a secret path is ALREADY mutation: allowed") -- so comparing
    // a secret-class candidate's class-default `mutation: allowed` against an overlapped kernel rule's
    // `mutation: prohibited` would read as a widening on every restrictive kernel directory a secret pattern's
    // implicit `**/` domain touches, for a rule that never asked for `mutation` at all.
    //
    // **AR75-F3 (corrected reasoning; the claim this comment used to make about WHY was measured wrong by
    // P2-AR-0075).** This does NOT rest on `decide()`'s `secret_locked` latch leaving `mutation` to "whichever
    // OTHER rule actually governs" a path -- it does not: `decide()` replaces its working `attrs` wholesale with
    // each matching rule's own merged fields, in order, and a matching `class: secret` rule is never skipped by
    // the latch (only a later NON-secret rule is), so a LATER secret candidate's own `mutation` field -- or its
    // base-default `"allowed"` when the field is absent, which is every rule's default regardless of class --
    // wins outright. Declaring `class: secret` on an appended rule therefore DOES widen `mutation` on paper
    // (`archive` restricted→allowed, `governance/kernel` prohibited→allowed), and excluding `mutation` from this
    // comparison for a secret candidate cannot be narrowed to catch that (an explicit `mutation` field would
    // separate the attack from the legitimate `.env` case that motivated the exclusion, but neither needs one --
    // both get `"allowed"` from the same base default, so they are indistinguishable at this field either way).
    // It is not exploitable TODAY for reasons that have nothing to do with this latch, and this comment must not
    // be read as more than what P2-AR-0075 actually measured: `tools.rs`'s per-token scan checks `sensitivity`
    // before `mutation` in an `if`/`else if`, and a `class: secret` path is always `sensitivity == "secret"`
    // first, so that branch gates on `new_secret_or_credential_access` before the `mutation` `else if` is ever
    // reached (the install still gates, on a DIFFERENT trigger); the two checks in this codebase that refuse a
    // `prohibited` mutation directly read the raw rules array rather than `decide().mutation`; declaring `secret`
    // simultaneously maximises `sensitivity`, `agent_read` and every index flag and minimises `export`, costing
    // the attacker every other dimension this function compares; and an explicit `export` override on the same
    // rule is still refused by the dimension loop below. This is a defence-in-depth gap this comment discloses,
    // not a proof that the exclusion is safe in general — it travels to the formal verifier as disclosed residual
    // risk rather than being resolved here (P2-HO-0052: reasoning only, no redesign of the latch).
    let new_is_secret = new.get("class").and_then(|v| v.as_str()) == Some(crate::paths::SECRET_CLASS);
    for (field, order) in [
        ("mutation", ["allowed", "restricted", "generated", "os-only", "prohibited"].as_slice()),
        ("agent_read", ["allowed", "restricted", "prohibited"].as_slice()),
        ("export", ["allowed", "denied"].as_slice()),
    ] {
        if field == "mutation" && new_is_secret {
            continue;
        }
        let (kv, nv) = (k.str(field), n.str(field));
        if rank_of(order, &nv) < rank_of(order, &kv) {
            return Err(format!(
                "{field} would be '{nv}' instead of '{kv}', which would widen filesystem/access scope"
            ));
        }
    }
    let (ks, ns) = (k.sensitivity(), n.sensitivity());
    if crate::paths::sensitivity_rank(&ns) < crate::paths::sensitivity_rank(&ks) {
        return Err(format!(
            "sensitivity would be '{ns}' instead of '{ks}', which would weaken it"
        ));
    }
    for field in ["semantic_index", "lexical_index", "graph_index", "code_index"] {
        if n.flag(field) && !k.flag(field) {
            return Err(format!("{field} would be true instead of false, widening indexing"));
        }
    }
    if n.default_retrieval() && !k.default_retrieval() {
        return Err("default_retrieval would be true instead of false, widening retrieval".into());
    }
    Ok(())
}

